message.content:
{
  "title": "The Mirror Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies ancient maps at camp.",
      "visual_description": "A ruined camp outside the city walls, Mara unrolls a parchment map while the oracle lamp flickers beside her.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 2,
      "caption": "Glass Diver peers through a broken window.",
      "visual_description": "Glass Diver kneels by a shattered window, his diving helmet reflecting the distant castle gates.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scampers ahead into the gate.",
      "visual_description": "The massive iron city gates hang ajar; Tin Fox slips through, key-wind tail spinning.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Sleeping Tax Collector blocks the path.",
      "visual_description": "In a courtyard, the Sleeping Tax Collector snores on a pile of ledgers, stamped papers fluttering.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "Oracle Lamp warns of a cursed tower.",
      "visual_description": "The oracle lamp's flame eye glares at a black tower with glowing runes, casting long shadows.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "Mara navigates the ruined market.",
      "visual_description": "Mara steps over fallen stalls under tattered royal banners, compass in hand.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Glass Diver swims through a mirror pool.",
      "visual_description": "Glass Diver dips into a cracked mirror on the ground, ripples of light distorting the scene.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Tin Fox reports back to Mara.",
      "visual_description": "Tin Fox clicks its metal jaws, pointing a paw towards a sealed magic door.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "Oracle Lamp illuminates the magic door.",
      "visual_description": "The magic door pulses with symbols; the oracle lamp's light reveals hidden patterns.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "Sleeping Tax Collector wakes briefly.",
      "visual_description": "The Sleeping Tax Collector stirs, stamps a paper blindly, and falls back asleep.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "Glass Diver emerges inside the tower.",
      "visual_description": "Glass Diver steps out of a wall mirror inside the cursed tower, coat dripping with shadow.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Mara searches for the rescue target.",
      "visual_description": "Mara consults her map in a dusty hall, footprints behind her on the floor.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "Tin Fox disables a trap on the stairs.",
      "visual_description": "Tin Fox gnaws through a tripwire, gear teeth glinting as a blade swings harmlessly.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "Oracle Lamp reveals a false wall.",
      "visual_description": "The lamp's flame casts a shadow that outlines a hidden passage behind a tapestry.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "Mara finds the locked chamber.",
      "visual_description": "Mara presses her ear to a heavy door, brass compass needle spinning wildly.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "Glass Diver opens the door from inside.",
      "visual_description": "Glass Diver's hand reaches through a keyhole, unlocking the door from the other side.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "The group escapes across a stone bridge.",
      "visual_description": "The team runs over a crumbling bridge, city ruins behind them, dawn ahead.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "Mara checks the map at the city edge.",
      "visual_description": "Mara marks the map with a final line, the rescued person unseen, as the group rests at the forest border.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    }
  ]
}

